#[test]
fn test_retrieve_merges_frontmatter_into_envelope() {
    let dir = setup_workspace_with_frontmatter_title();

    write(
        dir.path().join("task.md"),
        indoc! {"
            ---
            title: Do the thing
            status: ready
            gates:
            - tests
            - commit
            ---

            Body text here.
        "},
    )
    .unwrap();

    let (stdout, stderr, success) = run_iwe(dir.path(), &["-k", "task", "-d", "0"]);

    assert!(success, "stderr: {}", stderr);

    // title should be in envelope, not duplicated as separate field
    assert!(stdout.contains("  title: Do the thing"), "title in envelope: {}", stdout);
    assert!(stdout.contains("  status: ready"), "status merged: {}", stdout);
    assert!(stdout.contains("  gates:"), "gates merged: {}", stdout);
    // title should NOT appear as a separate field outside of document:
    let after_envelope = stdout.split("---\n\n").nth(1).unwrap_or("");
    assert!(!after_envelope.starts_with("title:"), "title not in body: {}", after_envelope);
    // Body text should still appear
    assert!(stdout.contains("Body text here."), "body present: {}", stdout);
}

