use std::borrow::Cow;

use crate::graph::Reader;
use crate::model::config::MarkdownOptions;
use crate::model::document::Document;

pub mod reader;

use reader::MarkdownEventsReader;
pub struct MarkdownReader {}

pub mod writer;

impl Default for MarkdownReader {
    fn default() -> Self {
        Self::new()
    }
}

impl MarkdownReader {
    pub fn new() -> MarkdownReader {
        MarkdownReader {}
    }
}

/// If `bare_frontmatter` is enabled and the document begins with what looks
/// like a YAML front-matter block (a run of `key:` lines, optionally with
/// indented continuations / list items, terminated by a blank line) then
/// wrap that leading block in `---` fences so the downstream
/// pulldown-cmark MetadataBlock machinery picks it up.
///
/// We accept any leading block whose first non-indented line begins with
/// `title: ` *or* whose block contains at least two distinct YAML keys.
/// The two-key threshold avoids misclassifying ordinary prose like
/// `Note: this is a note.` as front matter.
pub fn wrap_bare_frontmatter(content: &str) -> Cow<'_, str> {
    // Already fenced — leave alone.
    if content.starts_with("---") {
        return Cow::Borrowed(content);
    }

    // Find first true blank line (\n\n or \r\n\r\n).
    let (header, rest) = if let Some(pos) = content.find("\n\n") {
        (&content[..pos], &content[pos + 2..])
    } else if let Some(pos) = content.find("\r\n\r\n") {
        (&content[..pos], &content[pos + 4..])
    } else {
        // No blank line — entire content is header.
        (content.trim_end(), "")
    };

    if !looks_like_bare_frontmatter(header) {
        return Cow::Borrowed(content);
    }

    if rest.is_empty() {
        Cow::Owned(format!("---\n{}\n---\n", header))
    } else {
        Cow::Owned(format!("---\n{}\n---\n\n{}", header, rest))
    }
}

/// True if `header` looks like a YAML front-matter block.
fn looks_like_bare_frontmatter(header: &str) -> bool {
    let header = header.trim_end_matches('\r');
    if header.is_empty() {
        return false;
    }

    let mut key_count = 0usize;
    let mut first_line = true;
    let mut starts_with_title = false;

    for raw_line in header.lines() {
        let line = raw_line.trim_end_matches('\r');
        if line.is_empty() {
            // Blank line inside the header chunk would have terminated the
            // block above — treat as non-frontmatter to be safe.
            return false;
        }

        // Indented lines / list continuations are only meaningful after a
        // key has been seen.
        let first_byte = line.as_bytes()[0];
        if first_byte == b' ' || first_byte == b'\t' || first_byte == b'-' {
            if key_count == 0 {
                return false;
            }
            first_line = false;
            continue;
        }

        // Otherwise the line must look like `key:` or `key: value` where
        // `key` is a YAML-ish identifier.
        let colon = match line.find(':') {
            Some(i) => i,
            None => return false,
        };
        let key = &line[..colon];
        if key.is_empty() {
            return false;
        }
        if !key
            .chars()
            .all(|c| c.is_ascii_alphanumeric() || c == '_' || c == '-')
        {
            return false;
        }
        if !key.chars().next().unwrap().is_ascii_alphabetic() && key.chars().next().unwrap() != '_'
        {
            return false;
        }

        if first_line && line.starts_with("title:") {
            starts_with_title = true;
        }
        first_line = false;
        key_count += 1;
    }

    starts_with_title || key_count >= 2
}

impl Reader for MarkdownReader {
    fn document(&self, content: &str, markdown_options: &MarkdownOptions) -> Document {
        let effective = if markdown_options.bare_frontmatter {
            wrap_bare_frontmatter(content)
        } else {
            Cow::Borrowed(content)
        };

        let mut reader = MarkdownEventsReader::new_with_options(markdown_options);
        reader.read(&effective);

        Document {
            blocks: reader.blocks(),
            metadata: reader.metadata(),
        }
    }
}

